-- Paket contoh soal (bank publik milik sekolah demo) untuk tombol "Tambahkan contoh". Idempoten.
DO $$ DECLARE v_school uuid := (SELECT id FROM schools WHERE code='demo-sma'); v_admin uuid := (SELECT id FROM users WHERE school_id=(SELECT id FROM schools WHERE code='demo-sma') AND role='admin' ORDER BY created_at LIMIT 1); BEGIN
INSERT INTO shared_banks (school_id, slug, title, description, payload, created_by) VALUES (v_school, 'contoh-ipa', 'Contoh IPA', 'Makhluk hidup, zat, dan energi (SD–SMP)', '{"version": 1, "questions": [{"type": "pg", "content": {"text": "Bagian tumbuhan yang berfungsi menyerap air dan mineral adalah …", "options": ["Daun", "Akar", "Batang", "Bunga"]}, "answer_key": {"index": 1}, "points": 1, "rubric": null}, {"type": "pg", "content": {"text": "Perubahan wujud dari cair menjadi gas disebut …", "options": ["Membeku", "Mencair", "Menguap", "Mengembun"]}, "answer_key": {"index": 2}, "points": 1, "rubric": null}, {"type": "pg", "content": {"text": "Hewan yang berkembang biak dengan bertelur adalah …", "options": ["Kucing", "Ayam", "Sapi", "Kambing"]}, "answer_key": {"index": 1}, "points": 1, "rubric": null}, {"type": "benar_salah", "content": {"text": "Matahari merupakan sumber energi utama bagi bumi.", "options": ["Benar", "Salah"]}, "answer_key": {"index": 0}, "points": 1, "rubric": null}, {"type": "pgk_centang", "content": {"text": "Pilih semua yang termasuk sumber energi terbarukan.", "options": ["Tenaga surya", "Batu bara", "Tenaga angin", "Minyak bumi"]}, "answer_key": {"correct": [0, 2]}, "points": 2, "rubric": null}, {"type": "isian", "content": {"text": "Proses tumbuhan membuat makanan dengan bantuan cahaya matahari disebut …"}, "answer_key": {"accepted": ["fotosintesis"]}, "points": 1, "rubric": null}, {"type": "uraian", "content": {"text": "Jelaskan mengapa kita perlu menjaga kebersihan lingkungan sekitar sungai."}, "answer_key": {"manual": true}, "points": 3, "rubric": "Menyebut dampak sampah (banjir, penyakit, pencemaran) dan contoh tindakan menjaga kebersihan."}]}'::jsonb, v_admin) ON CONFLICT (slug) DO UPDATE SET payload = excluded.payload, title = excluded.title, description = excluded.description;
INSERT INTO shared_banks (school_id, slug, title, description, payload, created_by) VALUES (v_school, 'contoh-matematika', 'Contoh Matematika', 'Bilangan, pecahan, dan bangun datar', '{"version": 1, "questions": [{"type": "pg", "content": {"text": "Hasil dari 125 + 375 adalah …", "options": ["400", "450", "500", "550"]}, "answer_key": {"index": 2}, "points": 1, "rubric": null}, {"type": "pg", "content": {"text": "Hasil dari $\\frac{1}{2} + \\frac{1}{4}$ adalah …", "options": ["$\\frac{2}{6}$", "$\\frac{3}{4}$", "$\\frac{1}{6}$", "$\\frac{2}{4}$"]}, "answer_key": {"index": 1}, "points": 1, "rubric": null}, {"type": "pg", "content": {"text": "Keliling persegi dengan sisi 6 cm adalah …", "options": ["12 cm", "18 cm", "24 cm", "36 cm"]}, "answer_key": {"index": 2}, "points": 1, "rubric": null}, {"type": "benar_salah", "content": {"text": "Bilangan 17 adalah bilangan prima.", "options": ["Benar", "Salah"]}, "answer_key": {"index": 0}, "points": 1, "rubric": null}, {"type": "pgk_centang", "content": {"text": "Pilih semua bilangan genap.", "options": ["12", "15", "20", "27"]}, "answer_key": {"correct": [0, 2]}, "points": 2, "rubric": null}, {"type": "isian", "content": {"text": "Luas persegi panjang dengan panjang 8 cm dan lebar 5 cm adalah … cm²"}, "answer_key": {"accepted": ["40", "40 cm2", "40 cm²"]}, "points": 1, "rubric": null}, {"type": "uraian", "content": {"text": "Ibu membeli 3 kg apel seharga Rp20.000 per kg. Berapa uang kembalian jika ibu membayar Rp100.000? Tuliskan caranya."}, "answer_key": {"manual": true}, "points": 3, "rubric": "3 × 20.000 = 60.000; 100.000 − 60.000 = 40.000."}]}'::jsonb, v_admin) ON CONFLICT (slug) DO UPDATE SET payload = excluded.payload, title = excluded.title, description = excluded.description;
INSERT INTO shared_banks (school_id, slug, title, description, payload, created_by) VALUES (v_school, 'contoh-bahasa-indonesia', 'Contoh Bahasa Indonesia', 'Kata baku, sinonim, dan kalimat', '{"version": 1, "questions": [{"type": "pg", "content": {"text": "Penulisan kata baku yang tepat adalah …", "options": ["Apotik", "Apotek", "Atlit", "Nasehat"]}, "answer_key": {"index": 1}, "points": 1, "rubric": null}, {"type": "pg", "content": {"text": "Sinonim kata ''cerdas'' adalah …", "options": ["Pandai", "Malas", "Lambat", "Diam"]}, "answer_key": {"index": 0}, "points": 1, "rubric": null}, {"type": "pg", "content": {"text": "Kalimat yang menggunakan tanda baca dengan benar adalah …", "options": ["Ibu pergi ke pasar.", "ibu pergi ke pasar", "Ibu, pergi ke pasar", "Ibu pergi, ke pasar."]}, "answer_key": {"index": 0}, "points": 1, "rubric": null}, {"type": "benar_salah", "content": {"text": "Antonim kata ''tinggi'' adalah ''rendah''.", "options": ["Benar", "Salah"]}, "answer_key": {"index": 0}, "points": 1, "rubric": null}, {"type": "isian", "content": {"text": "Lawan kata dari ''rajin'' adalah …"}, "answer_key": {"accepted": ["malas"]}, "points": 1, "rubric": null}, {"type": "uraian", "content": {"text": "Tuliskan satu kalimat ajakan untuk menjaga kebersihan kelas."}, "answer_key": {"manual": true}, "points": 3, "rubric": "Kalimat ajakan (ayo/mari), berisi ajakan menjaga kebersihan, diakhiri tanda baca yang tepat."}]}'::jsonb, v_admin) ON CONFLICT (slug) DO UPDATE SET payload = excluded.payload, title = excluded.title, description = excluded.description;
INSERT INTO shared_banks (school_id, slug, title, description, payload, created_by) VALUES (v_school, 'contoh-pancasila', 'Contoh Pendidikan Pancasila', 'Pancasila dan kehidupan sehari-hari', '{"version": 1, "questions": [{"type": "pg", "content": {"text": "Simbol sila pertama Pancasila adalah …", "options": ["Bintang", "Rantai", "Pohon beringin", "Kepala banteng"]}, "answer_key": {"index": 0}, "points": 1, "rubric": null}, {"type": "pg", "content": {"text": "Lambang negara Indonesia adalah …", "options": ["Garuda Pancasila", "Bendera Merah Putih", "Monas", "Rumah adat"]}, "answer_key": {"index": 0}, "points": 1, "rubric": null}, {"type": "pg", "content": {"text": "Sikap menghargai teman yang berbeda agama mencerminkan sila ke- …", "options": ["Satu", "Dua", "Tiga", "Lima"]}, "answer_key": {"index": 0}, "points": 1, "rubric": null}, {"type": "benar_salah", "content": {"text": "Musyawarah untuk mufakat merupakan pengamalan sila keempat.", "options": ["Benar", "Salah"]}, "answer_key": {"index": 0}, "points": 1, "rubric": null}, {"type": "pgk_centang", "content": {"text": "Pilih semua contoh sikap gotong royong.", "options": ["Kerja bakti membersihkan lingkungan", "Mencontek saat ujian", "Membantu teman yang kesulitan", "Membuang sampah sembarangan"]}, "answer_key": {"correct": [0, 2]}, "points": 2, "rubric": null}, {"type": "uraian", "content": {"text": "Sebutkan dua contoh pengamalan sila kelima di sekolah."}, "answer_key": {"manual": true}, "points": 3, "rubric": "Contoh adil: berbagi tugas piket merata, menghargai hasil kerja teman, tidak memilih-milih teman."}]}'::jsonb, v_admin) ON CONFLICT (slug) DO UPDATE SET payload = excluded.payload, title = excluded.title, description = excluded.description;
END $$;
SELECT slug, jsonb_array_length(payload->'questions') n FROM shared_banks ORDER BY slug;
